<script setup>
import { ref, nextTick, watch, useId } from 'vue'
import { FileText, Folder, Sparkles, CalendarDays, Check, ArrowRight, Send, WandSparkles } from 'lucide-vue-next'
import EdzioAvatar from './EdzioAvatar.vue'
const props = defineProps({ paused: Boolean, compactHero: Boolean, initialTab: { type: String, default: 'documents' } })
const instanceId = useId()
const active = ref(props.initialTab)
watch(() => props.initialTab, value => { active.value = value })
const sorted = ref(false)
const tabs = [
  { id: 'documents', icon: Folder, label: 'Dokumenty' },
  { id: 'ai', icon: Sparkles, label: 'Edzio AI' },
  { id: 'calendar', icon: CalendarDays, label: 'Terminarz' }
]
function moveTab(step) {
  active.value = tabs[(tabs.findIndex(tab => tab.id === active.value) + step + tabs.length) % tabs.length].id
  nextTick(() => document.getElementById('demo-tab-' + instanceId + '-' + active.value)?.focus())
}
const files = [
  { name: 'Umowa o współpracy.pdf', type: 'Umowy', color: 'purple' },
  { name: 'Oferta dla klienta.pdf', type: 'Oferty', color: 'green' },
  { name: 'Protokół spotkania.docx', type: 'Spotkania', color: 'orange' }
]
</script>

<template>
  <section class="product-showcase" :class="{ 'showcase-paused': paused, 'showcase-hero': compactHero }" :aria-labelledby="compactHero ? undefined : 'showcase-title-' + instanceId">
    <div v-if="!compactHero" class="showcase-heading"><span class="showcase-eyebrow">Zobacz, jak łapiesz flow</span><h2 :id="'showcase-title-' + instanceId">Mniej klikania w kółko.<br>Więcej spraw do przodu.</h2><p>Wybierz, co chcesz uporządkować. Reszta zaczyna się od jednego kroku.</p></div>
