    </div>
    <div :id="'demo-panel-' + instanceId + '-' + active" class="showcase-window" :role="compactHero ? 'group' : 'tabpanel'" :aria-label="compactHero ? (active === 'ai' ? 'Edzio AI' : 'Terminarz') : undefined" :aria-labelledby="compactHero ? undefined : 'demo-tab-' + instanceId + '-' + active" tabindex="0">
      <div class="showcase-window-bar"><span class="window-dots"><i></i><i></i><i></i></span><span>Space & Flow / {{ tabs.find(tab => tab.id === active).label }}</span><small>Przykład działania</small></div>
      <div v-if="active === 'documents'" class="demo-document-layout">
        <div class="demo-copy"><span class="demo-step">01 / Przestrzeń na dokumenty</span><h3>Każdy plik.<br>Na swoim miejscu.</h3><p>Od luźnych załączników do przejrzystych folderów. Poukładaj dokumenty według spraw i wracaj do nich bez szukania.</p><button class="demo-order-button" :aria-pressed="sorted" @click="sorted = !sorted"><WandSparkles :size="17" />{{ sorted ? 'Pokaż jeszcze raz' : 'Zróbmy porządek' }}<ArrowRight :size="16" /></button></div>
        <div class="demo-file-stage" :class="{ 'is-sorted': sorted }">
          <div class="demo-file-grid"></div>
          <div v-for="(file, i) in files" :key="file.name" class="demo-file" :class="['demo-file-' + i, file.color]"><span class="demo-file-symbol"><FileText :size="22" /></span><div><strong>{{ file.name }}</strong><small>{{ sorted ? file.type : 'Plik do uporządkowania' }}</small></div><Check class="demo-sorted-check" :size="17" /></div>
