        <div class="demo-calendar"><div class="demo-calendar-top"><CalendarDays :size="18" /><strong>Plan tygodnia</strong><span>Widok przykładowy</span></div><div class="demo-week"><span v-for="day in ['Pon', 'Wt', 'Śr', 'Czw', 'Pt']" :key="day">{{ day }}</span><div class="demo-week-cells"><div v-for="i in 15" :key="i"></div></div><div class="demo-calendar-event event-meeting"><span></span>Spotkanie zespołu<small>10:00 · 30 min</small></div><div class="demo-calendar-event event-document"><span></span>Oferta dla klienta<small>Sprawdź i zaakceptuj</small></div><div class="demo-calendar-event event-done"><Check :size="12" /> Umowa gotowa</div><span class="demo-time-line"></span></div><div class="demo-calendar-notice"><Check :size="14" /> Małe kroki. Zamknięte sprawy.</div></div>
      </div>
    </div>
  </section>
